    "text.d9dd56ca8ae3": "BACKEND CONTRACTS · V1",
    "text.daa17d511566": "Start exploring",
    "text.db51cb6cb1e7": "Login and real payments",
    "text.db680ac702a7": "Kuaixie Travel Shopping",
    "text.dbe3bff8df4c": "The backend has no endpoint to issue a login JWT. Use an external trusted identity provider; the frontend does not invent tokens.",
    "text.dcd9bb797164": "Configure a valid JWT in Profile before calling protected APIs.",
    "text.de43b5cd9809": "Current API ·",
    "text.de80bdbd702a": "Route",
    "text.dfd6b7aab1c8": "Inventory",
    "text.dfe4559f96f4": "Refresh live data ↻",
    "text.e0038c70ad9e": "Learn how route sharing works",
    "text.e027b971609d": "Built on actual Spring Boot Controllers · Some capabilities require backend development",
    "text.e0f89e57c86a": "real routes · Requests go straight to the backend.",
    "text.e12c70b1a031": "Published",
